import 'package:nus_style/http/api_client.dart';
import 'package:nus_style/model/cartridge_models.dart';

class CartridgeRepository {
  CartridgeRepository({ApiClient? api}) : _api = api ?? ApiClient.instance;

  final ApiClient _api;

  /// `GET /api/v1/cartridge`
  Future<List<Cartridge>> listCartridges() async {
    final response = await _api.get('/api/v1/cartridge');
    return (response.data as List<dynamic>)
        .map((e) => Cartridge.fromMap(e as Map<String, dynamic>))
        .toList();
  }
}
